    // MARK: - WiSo

    private static let w24wLage = "Ausgangssituation: Die EcoTec GmbH ist ein IT-Service-Unternehmen und hat 25 Mitarbeiter. Die folgenden Aufgaben beziehen sich auf dieses Unternehmen."
    private static func tw(_ nr: Int, _ topic: ExamTopic, _ text: String, _ options: [String], _ expl: String) -> ExamCard {
        ihkChoice("ihk-ap2-2024w-wiso-\(nr)", topic, w24wLage, "\(nr). Aufgabe\n\(text)", options, "\(w24Muster) \(expl)")
    }
    private static func twm(_ nr: Int, _ topic: ExamTopic, _ text: String, correct: [String], wrong: [String], _ expl: String) -> ExamCard {
        ihkMultiple("ihk-ap2-2024w-wiso-\(nr)", topic, w24wLage, "\(nr). Aufgabe\n\(text)", correct: correct, wrong: wrong, "\(w24Muster) \(expl)")
    }
    private static let w24wOrga = "[Grafik zur 13. und 14. Aufgabe als Text, Organigramm: Leitung mit seitlich angehängter Rechtsabteilung; darunter Sales (Vertrieb), Public Relations, Personal, Organisation/IT; weitere Kästen Verwaltung, Nachhaltigkeitsmanagement, Versand, Buchhaltung, IT-Service. Die genaue Anordnung der unteren Ebene ist im Scan nicht sicher lesbar.]"
    private static let w24wMarkt = "Situation zur 16. und 17. Aufgabe: Die EcoTec GmbH ist in den folgenden beiden Märkten tätig: spezielle IT-Dienstleistungen für Medikamentenabrechnungen. Hier gibt es vier Mitbewerber. Außerdem bietet die EcoTec GmbH für eine Vielzahl von Privathaushalten und Unternehmen allgemeine IT-Dienstleistungen für Steuerabrechnungen an. In diesem zweiten Bereich gibt es eine Vielzahl von Konkurrenten."
    private static let w24wGmbH = "Situation zur 21. und 22. Aufgabe: Drei ehemalige Mitarbeitende der EcoTec GmbH wollen sich selbstständig machen und ein Unternehmen als GmbH gründen. Die Einlagen verteilen sich wie folgt: John Walsch mit einer Einlage in Höhe von 50.000 EUR, Susanne Venga mit einer Einlage in Höhe von 20.000 EUR, Denis Ozgül mit einer Einlage in Höhe von 15.000 EUR. Als Geschäftsführerin für die neue GmbH wird Claudia Müller eingestellt. Im Gesellschaftsvertrag wird auf die gesetzlichen Bestimmungen bezüglich Haftung und Vertretung verwiesen."

    static let ihkW2024WiSo: [ExamCard] = [
        tw(1, .schutz, "Moritz Monion hat am 02.03. Geburtstag, ist 17 Jahre alt und beginnt am 01.08.2024 seine Ausbildung bei der EcoTec GmbH. 2025 erhält er 30 Urlaubstage.\nErmitteln Sie, wie viele Werktage Herr Monion mehr erhält, als im Jugendarbeitsschutzgesetz als Mindesturlaub vorgeschrieben ist.\nJugendarbeitsschutzgesetz § 19 Urlaub: (1) Der Arbeitgeber hat Jugendlichen für jedes Kalenderjahr einen bezahlten Erholungsurlaub zu gewähren. (2) Der Urlaub beträgt jährlich mindestens 30 Werktage, wenn der Jugendliche zu Beginn des Kalenderjahrs noch nicht 16 Jahre alt ist, mindestens 27 Werktage, wenn der Jugendliche zu Beginn des Kalenderjahrs noch nicht 17 Jahre alt ist, mindestens 25 Werktage, wenn der Jugendliche zu Beginn des Kalenderjahrs noch nicht 18 Jahre alt ist.",
           ["5 Werktage", "3 Werktage", "0 Werktage", "6 Werktage", "2 Werktage"],
           "5. Am 01.01.2025 ist er 17, also noch nicht 18: Mindesturlaub 25 Werktage; 30 – 25 = 5."),
        tw(2, .ausbildung, "Die EcoTec GmbH schließt Ausbildungsverträge mit diversen Auszubildenden ab.\nWelcher der folgenden Punkte ist nicht zwingend vertraglich in Ausbildungsverträgen festzuhalten?",
           ["Regelungen zur Gleitzeit", "Art, sachliche und zeitliche Gliederung sowie Ziel der Berufsausbildung", "Beginn und Dauer der Berufsausbildung", "Dauer der regelmäßigen täglichen Ausbildungszeit", "Ausbildungsmaßnahmen außerhalb der Ausbildungsstätte"],
           "Ziffer 4. Die Pflichtangaben stehen in § 11 BBiG; Gleitzeit gehört nicht dazu."),
        tw(3, .ausbildung, "Herr Monion hat Fragen bezüglich der Probezeit.\nWie lang muss die Probezeit laut Berufsbildungsgesetz in der Ausbildung mindestens sein?",
           ["1 Monat", "2 Monate", "3 Monate", "4 Monate", "Eine Probezeit ist nicht zwingend notwendig"],
           "Ziffer 1. Mindestens ein Monat, höchstens vier Monate (§ 20 BBiG)."),
        tw(4, .ausbildung, "Justin Höhler, Mitauszubildender von Herrn Monion, kündigt seinen Ausbildungsvertrag während der Probezeit.\nWelche der folgenden Feststellung hierzu entspricht dem Berufsbildungsgesetz?",
           ["Beide Seiten können das Berufsausbildungsverhältnis in der Probezeit ohne Angabe von Gründen und ohne Einhaltung einer Kündigungsfrist kündigen.", "Die Kündigung eines Ausbildungsverhältnisses kann mündlich erfolgen.", "Beide Seiten können das Berufsausbildungsverhältnis nur in der ersten Hälfte der Probezeit und zwingend mit Einhaltung einer Kündigungsfrist kündigen.", "In Betrieben, in denen ein Betriebsrat besteht, muss dieser jeder Kündigung während der Probezeit durch den Arbeitgeber zustimmen.", "Während einer Berufsausbildung kann vom Arbeitgeber nicht, auch nicht in der Probezeit, gekündigt werden."],
           "Ziffer 3. § 22 BBiG: in der Probezeit jederzeit ohne Frist; die Kündigung muss schriftlich erfolgen. (Im Scan endet Ziffer 2 nach „Kündigungsfrist“; das abschließende „kündigen.“ ist sinngemäß ergänzt.)"),
        tw(5, .mitbestimmung, "In der EcoTec GmbH soll ein neuer Betriebsrat gewählt werden.\nWelche der folgenden Personengruppen ist nach dem Betriebsverfassungsgesetz (BetrVG) in den Betriebsrat wählbar (passives Wahlrecht)?",
           ["Alle Wahlberechtigten, die das 18. Lebensjahr vollendet haben und mindestens sechs Monate im Betrieb beschäftigt sind.", "Alle Wahlberechtigten, die über 16 Jahre alt sind.", "Alle Betriebsangehörigen", "Alle Wahlberechtigten, die mindestens das 21. Lebensjahr vollendet haben und seit einem Monat im Betrieb beschäftigt sind.", "Alle Wahlberechtigten, die der EcoTec GmbH seit mindestens sechs Wochen angehören."],
           "Ziffer 3. § 8 BetrVG."),
        tw(6, .mitbestimmung, "Maike Schröder, eine Kollegin von Herrn Monion, beschäftigt sich mit dem Aufgabenbereich des Betriebsrats. Sie liest unter anderem den folgenden Satz: „Der Betriebsrat sorgt in den Unternehmen für die Umsetzung und Einhaltung von Tarifverträgen.“ Sie hat bisher nur Gewerkschaften mit Tarifverträgen in Verbindung gebracht.\nWelche der folgenden Darstellungen von Gewerkschaften ist zutreffend? Gewerkschaften ...",
           ["können bei Streitigkeiten zwischen Arbeitgebern und Arbeitnehmern den organisierten Arbeitnehmern Rechtsbeistand leisten.", "sind in den Betrieben für die Schlichtung von Auseinandersetzungen zwischen Arbeitnehmern und Arbeitgebern zuständig.", "handeln mit den Arbeitgeberverbänden auch Betriebsvereinbarungen aus.", "haben die Aufgabe, die Betriebsratswahlen zu kontrollieren.", "haben bei Tarifverhandlungen für die Belange aller Arbeitnehmer einzutreten."],
           "Ziffer 3. Gewerkschaften leisten ihren Mitgliedern Rechtsschutz; Betriebsvereinbarungen schließen Arbeitgeber und Betriebsrat."),
        twm(7, .mitbestimmung, "Herr Monion beschäftigt sich mit dem Zustandekommen von Tarifverträgen. Ihm liegt der folgende zeitliche Ablaufplan vor. Herr Monion ist sich sicher, dass dort die Reihenfolge der Schritte durcheinandergeraten ist.\nAblaufplan: 1 Fristgerechte Kündigung des bestehenden Tarifvertrags – 2 Aufnahme der Tarifverhandlungen durch die Tarifparteien – 3 Urabstimmung über einen Arbeitskampf mit nachfolgendem Streik – 4 Erklärung des Scheiterns der Tarifverhandlungen durch eine der Tarifparteien – 5 Neue Verhandlungen bei Aussetzung des Streiks – 6 Urabstimmung über die Verhandlungsergebnisse – 7 Zustimmung der Tarifparteien zum Ergebnis\nWelche der folgenden Schritte wurden aus Versehen vertauscht? (Zwei Schritte)",
            correct: ["Urabstimmung über einen Arbeitskampf mit nachfolgendem Streik", "Erklärung des Scheiterns der Tarifverhandlungen durch eine der Tarifparteien"],
            wrong: ["Fristgerechte Kündigung des bestehenden Tarifvertrags", "Aufnahme der Tarifverhandlungen durch die Tarifparteien", "Neue Verhandlungen bei Aussetzung des Streiks", "Urabstimmung über die Verhandlungsergebnisse", "Zustimmung der Tarifparteien zum Ergebnis"],
            "Ziffern 3 und 4. Erst wird das Scheitern erklärt, dann folgt die Urabstimmung über den Streik."),
        tw(8, .mitbestimmung, "In der EcoTec GmbH wird aktuell überlegt, die tariflich festgelegten Arbeitsbedingungen in einzelnen Punkten zu ändern.\nWann sind solche Änderungen zulässig? Die Änderung ist zulässig, wenn ...",
           ["sie zugunsten der Arbeitnehmer erfolgt.", "die Berufsgenossenschaft der Änderung zustimmt.", "die Landesregierung der Änderung zustimmt.", "sie zugunsten der EcoTec GmbH erfolgt.", "sie von der Bundesagentur für Arbeit genehmigt wird."],
           "Ziffer 1. Günstigkeitsprinzip (§ 4 Abs. 3 TVG)."),
        tw(9, .mitbestimmung, "Die EcoTec GmbH veröffentlicht in ihrem Intranet die aktuell gültigen Betriebsvereinbarungen.\nVon wem werden diese Betriebsvereinbarungen abgeschlossen? Die Betriebsvereinbarungen werden abgeschlossen von ...",
           ["der Geschäftsleitung der EcoTec GmbH und dem Betriebsrat.", "den Tarifparteien, also dem Arbeitgeberverband und der örtlich zuständigen Industrie- und Handelskammer.", "der Industrie- und Handelskammer und dem Betriebsrat der EcoTec GmbH.", "dem Betriebsrat der EcoTec GmbH und der zuständigen Arbeitsagentur.", "dem Betriebsrat der EcoTec GmbH und der zuständigen Industrie- und Handelskammer."],
           "Ziffer 5. § 77 BetrVG."),
        ihkMatch("ihk-ap2-2024w-wiso-10", .recht, w24wLage,
                 "10. Aufgabe\nDie 17-jährige Daniela Schubert ist Auszubildende im ersten Ausbildungsjahr bei der EcoTec GmbH. Sie bittet Herrn Monion um Informationen, in welchen Rechtsgrundlagen sie sich bezüglich der nachstehenden Angelegenheiten informieren kann.\nIn welchen Gesetzen findet Herr Monion die Rechtsgrundlagen, die zu den jeweiligen Angelegenheiten passen?\nRechtsgrundlagen: Jugendarbeitsschutzgesetz, Berufsbildungsgesetz, Kündigungsschutzgesetz, Betriebsverfassungsgesetz, Bürgerliches Gesetzbuch",
                 pairs: [("a) Frau Schubert möchte wissen, ob das Berufsausbildungsverhältnis gekündigt werden kann.", "Berufsbildungsgesetz"),
                         ("b) Frau Schubert möchte wissen, wie viel Pausenzeiten ihr zustehen.", "Jugendarbeitsschutzgesetz"),
                         ("c) Frau Schubert möchte wissen, welche Aufgaben die Jugend- und Auszubildendenvertretung hat.", "Betriebsverfassungsgesetz")],
                 extra: ["Kündigungsschutzgesetz", "Bürgerliches Gesetzbuch"],
                 "\(w24Muster) a) 2 Berufsbildungsgesetz (§ 22), b) 1 Jugendarbeitsschutzgesetz (§ 11), c) 4 Betriebsverfassungsgesetz (§ 70)."),
        tw(11, .mitbestimmung, "Bei der EcoTec GmbH gibt es eine Jugend- und Auszubildendenvertretung (JAV), in der sich Herr Monion engagieren möchte.\nWelcher der folgenden Aussagen zur JAV ist zutreffend?",
           ["Eine JAV kann nur gewählt werden, wenn bereits ein Betriebsrat besteht.", "Die regelmäßige Amtszeit in der JAV beträgt vier Jahre.", "Das passive Wahlrecht für die JAV endet mit Vollendung des 18. Lebensjahres.", "Das Mindestalter für das aktive Wahlrecht beträgt 16 Jahre.", "Das aktive Wahlrecht für die JAV endet immer mit Vollendung des 18. Lebensjahres."],
           "Ziffer 5. Die JAV setzt einen Betriebsrat voraus (§ 60 BetrVG); die Amtszeit beträgt zwei Jahre, wählbar ist man bis 25, für Auszubildende gibt es keine Altersgrenze beim Wahlrecht."),
        tw(12, .mitbestimmung, "Herr Monion möchte sich als Kandidat zur JAV aufstellen lassen.\nWelche der folgenden Voraussetzungen muss er u. a. dafür erfüllen? Herr Monion ...",
           ["darf nicht Mitglied des Betriebsrats sein.", "muss die deutsche Staatsangehörigkeit besitzen.", "muss im zweiten Ausbildungsjahr sein.", "darf während der Amtszeit das 25. Lebensjahr nicht überschreiten.", "muss bereits seit mindestens drei Monaten im Betrieb beschäftigt sein."],
           "Ziffer 1. Mitglieder des Betriebsrats können nicht in die JAV gewählt werden (§ 61 Abs. 2 BetrVG); maßgeblich ist das Alter bei Beginn der Amtszeit, nicht während."),
        tw(13, .unternehmen, "\(w24wOrga)\nHerr Monion zeigt Frau Schröder das abgebildete Organigramm der EcoTec GmbH.\nWelches der folgenden Leitungssysteme liegt diesem Organigramm zugrunde?",
           ["Stabliniensystem", "Liniensystem", "Mehrliniensystem", "Matrixorganisation", "Spartenorganisation"],
           "Ziffer 2. Linienorganisation mit einer Stabsstelle (Rechtsabteilung)."),
        tw(14, .unternehmen, "\(w24wOrga)\nDarüber hinaus erläutert Herr Monion ihr die Organisationsstruktur aus Aufgabe 13.\nWelche der folgenden Aussagen dazu ist zutreffend?",
           ["Die Rechtsabteilung berät die Geschäftsleitung, ist jedoch gegenüber den Angestellten der EcoTec GmbH nicht weisungsbefugt.", "Die IT-Abteilung ist als Stabsstelle organisiert.", "Stabsstellen kommen auf keiner der Leitungsebenen der EcoTec GmbH vor.", "Das Nachhaltigkeitsmanagement der EcoTec GmbH untersteht der Sales-Abteilung.", "Die Leitung Personalmanagement ist nicht an die Weisungen der Geschäftsführung gebunden."],
           "Ziffer 5. Stabsstellen beraten und haben keine Weisungsbefugnis."),
        tw(15, .wirtschaft, "Herrn Monion liegen folgende Zahlen bezüglich der aktuellen Entwicklung der wirtschaftlichen Situation in Europa vor (1. / 2. / 3. / 4. Quartal):\nBruttoinlandsprodukt in Billionen EUR: 3,87 / 3,7 / 3,5 / 3,3\nArbeitslosenquote: 8,5 % / 9 % / 10 % / 11,5 %\nWirtschaftswachstum: 1 % / –1,1 % / –1,5 % / –2 %\nMit welchem der folgenden Begriffe können Sie die gesamtwirtschaftliche Situation bezogen auf das ganze Jahr beschreiben?",
           ["Abschwung (Rezession)", "Aufschwung", "Stillstand (Stagnation)", "Höchststand (Boom)", "Inflation"],
           "Ziffer 5. Sinkendes BIP, negatives Wachstum und steigende Arbeitslosigkeit."),
        tw(16, .wirtschaft, "\(w24wMarkt)\nWelche der folgenden Aussagen beschreibt und begründet die vorliegenden Marktformen korrekt?",
           ["Der Markt für allgemeine IT-Dienstleistungen für Steuerabrechnungen weist auf ein Polypol hin, da neben der EcoTec GmbH eine hohe Zahl an Anbietern auf eine Vielzahl von Nachfragern trifft.", "Bei den Medikamentenabrechnungen ist die Marktform des Polypols gegeben, da viele Unternehmen und Haushalte als Nachfrager auftreten.", "Das Nachfrageoligopol kennzeichnet den Markt für Steuerabrechnungen, da mit Unternehmen und Haushalten nur zwei große Gruppen von Nachfragern auftreten.", "Da neben der EcoTec GmbH nur wenige Anbieter auf dem Markt für Medikamentenabrechnungen zu finden sind, liegt die Marktform des Angebotsmonopols vor.", "Es liegt ein Quasi-Monopol als Marktform vor, da es insgesamt lediglich vier Anbieter für Steuerabrechnungen gibt, die somit automatisch eine marktbeherrschende Stellung innehaben."],
           "Ziffer 2. Viele Anbieter und viele Nachfrager: Polypol. Bei den Medikamentenabrechnungen (fünf Anbieter) liegt ein Angebotsoligopol vor."),
        tw(17, .wirtschaft, "\(w24wMarkt)\nWelchen der folgenden Unterschiede weist der Markt für Steuerabrechnungen zu dem Modell des vollkommenen Marktes bzw. der vollständigen Konkurrenz auf?",
           ["Das Modell des vollkommenen Marktes unterstellt die Homogenität der Güter; dies ist im Fall des Marktes für Steuerabrechnungen jedoch nicht gegeben, da die Anbieter ihre Software mit verschiedenen Merkmalen und Eigenschaften auf den Markt bringen.", "In dem Markt der vollständigen Konkurrenz kann der Staat zum Schutz der Verbraucher Mindestpreise und Höchstpreise festlegen. Dies ist für den Markt für Steuerabrechnungen nicht möglich.", "Der Markt für Steuerabrechnungen stellt einen Verkäufermarkt dar. Im Modell der vollständigen Konkurrenz liegt dagegen nur der Käufermarkt vor.", "Im Modell des vollkommenen Marktes wird von jedem Anbieter eine eigenständige und unabhängige Preispolitik betrieben.", "Da es sich im vorliegenden Fall nur um wenige Anbieter von Steuerabrechnungen handelt, liegt auf der Nachfrageseite vollständige Markttransparenz vor. Diese ist im Modell der vollständigen Konkurrenz nicht gegeben."],
           "Ziffer 5. Der vollkommene Markt setzt gleichartige (homogene) Güter voraus; im Modell sind alle Anbieter Preisnehmer."),
        ihkMatch("ihk-ap2-2024w-wiso-18", .unternehmen, w24wLage,
                 "18. Aufgabe\nDie EcoTec GmbH stellt sich in ihrem Leitbild unter anderem auch als „lernende Organisation“ dar. Ein Aspekt hiervon ist die regelmäßige Anpassung und Aktualisierung der Unternehmensziele. Bei der Formulierung der Unternehmensziele kann es zu Konflikten zwischen einzelnen Zielen kommen.\nWelche der folgenden Zielarten lassen sich den nachstehenden Zielsetzungspaaren zuordnen?\nZielarten: Komplementäre Ziele, Konkurrierende Ziele, Indifferente Ziele",
                 pairs: [("a) Mitarbeiterzufriedenheit erhöhen ↔ erhöhte Ausgaben für Verpackungen vermeiden", "Indifferente Ziele"),
                         ("b) Einkauf ausschließlich der preisgünstigsten Produkte ↔ Erlangung eines Gütesiegels in der Produktion", "Konkurrierende Ziele"),
                         ("d) Kundenzufriedenheit durch kompetente Mitarbeitende ↔ Mitarbeiterqualifikationen durch Fortbildungen erhöhen", "Komplementäre Ziele")],
                 extra: [],
                 "\(w24Muster) a) 3, b) 2, c) 3, d) 1, e) 1. Hier sind a), b) und d) übernommen; c) (gutes Arbeitsklima ↔ Recycling der Verpackungen) ist indifferent, e) (Bezugskosten minimieren ↔ Gewinnmaximierung) komplementär."),
        tw(19, .nachhaltigkeit, "Die EcoTec GmbH verfolgt auch soziale Ziele.\nWelche der folgenden Maßnahmen orientiert sich nicht an sozialen Zielen?",
           ["Sammeln der Verpackungsabfälle aus dem Wareneingang", "Verwenden von fair gehandelten Produkten", "Verfolgung strenger Diversity- und Compliance-Regelungen", "Beteiligung der Arbeitenden am Unternehmenserfolg", "Einrichten eines betrieblichen Kindergartens"],
           "Ziffer 5. Das Sammeln von Verpackungsabfällen ist ein ökologisches Ziel."),
        tw(20, .arbeitsrecht, "Einem Mitarbeiter der EcoTec GmbH wurde nach dreijähriger Betriebszugehörigkeit betriebsbedingt gekündigt.\nWelchen der folgenden Gründe kann eine betriebsbedingte Kündigung haben?",
           ["Wegfall des Arbeitsplatzes durch Standortschließung", "Zeitablauf des befristeten Arbeitsvertrages", "Trunkenheit am Arbeitsplatz", "Mangelndes Fachwissen", "Grobe Beleidigung eines Vorgesetzten"],
           "Ziffer 3. Trunkenheit und Beleidigung sind verhaltensbedingt, mangelndes Fachwissen personenbedingt; ein befristeter Vertrag endet ohne Kündigung."),
        tw(21, .unternehmen, "\(w24wGmbH)\nDie drei Gesellschafter wollen die GmbH rechtswirksam gründen.\nWelcher der folgenden Sachverhalte entspricht den gesetzlichen Regelungen zur GmbH?",
           ["Die Einlagen der drei Gesellschafter übersteigen das gesetzlich geforderte Mindestkapital der neuen GmbH.", "Eine Eintragung der GmbH ins Handelsregister muss nicht zwangsläufig beantragt werden.", "Der Name des neuen Unternehmens in dem Antrag könnte auch auf „EcoTec GmbH“ lauten.", "Die Geschäftsführung des neuen Unternehmens muss durch eine außenstehende Person erfolgen, da zur Vermeidung von Interessenkonflikten Gesellschafter einer GmbH nicht auch deren Geschäfte führen dürfen.", "Der Gesellschaftsvertrag zwischen den drei Gesellschaftern kann auch mündlich abgeschlossen werden, um rechtswirksam sein zu können."],
           "Ziffer 4. 85.000 EUR liegen über dem Mindeststammkapital von 25.000 EUR. Eintragung und notarielle Form sind Pflicht, Gesellschafter dürfen Geschäftsführer sein."),
        tw(22, .unternehmen, "\(w24wGmbH)\nDie neu gegründete GmbH erwirbt einen neuen Server.\nWie ist die Haftung der GmbH gegenüber dem Verkäufer geregelt?",
           ["Die GmbH haftet gegenüber dem Verkäufer mit dem gesamten Betriebsvermögen.", "Dem Verkäufer gegenüber haftet nur der Gesellschafter mit der höchsten Einlage.", "Die GmbH haftet mit ihrem Stammkapital und die drei Gesellschafter zusätzlich auch mit ihrem Privatvermögen.", "Die GmbH haftet dem Verkäufer der Ware gegenüber nur bis zur Höhe des gesetzlich festgelegten und einzuzahlenden Mindestkapitals.", "Die GmbH haftet gegenüber dem Verkäufer nur mit den liquiden Mitteln der Gesellschaft."],
           "Ziffer 3. Die GmbH haftet mit ihrem gesamten Gesellschaftsvermögen (§ 13 GmbHG), die Gesellschafter nicht privat."),
        // 23. bis 28. Aufgabe (ökologisches Ziel, Emissionen, „Blauer Engel“, Arbeitsschutzbeauftragter,
        // Brandfall, Stressreduzierung) entsprechen Sommer 2026, WiSo 19 bis 24, und werden nicht doppelt angelegt.
        tw(29, .arbeitsrecht, "Die EcoTec GmbH legt sowohl während des Einstellungsverfahrens als auch während der Beschäftigung großen Wert auf die Gleichbehandlung aller Mitarbeitenden.\nWelche der folgenden Aussagen trifft auf das Allgemeine Gleichbehandlungsgesetz (AGG) zu?",
           ["Das AGG regelt unter anderem, dass Benachteiligungen aus Gründen des Geschlechts, der Religion oder Weltanschauung nicht zulässig sind.", "Das AGG gilt nicht für Auszubildende.", "Bei Verstoß gegen das AGG haben die Betroffenen keinen Anspruch auf Schadenersatz.", "Stellenausschreibungen müssen nicht zwingend geschlechtsneutral ausgeschrieben werden.", "Die Benachteiligungsverbote des AGG erstrecken sich nicht auf Ungleichbehandlungen bei dem beruflichen Aufstieg sowie bei den Arbeitsbedingungen."],
           "Ziffer 3. § 1 AGG; das Gesetz gilt auch für Auszubildende, gewährt Schadenersatz und umfasst Aufstieg und Arbeitsbedingungen."),
        tw(30, .arbeitsrecht, "Die EcoTec GmbH plant, zwei Fachinformatiker Anwendungsentwicklung (m/w/d) einzustellen.\nWelche der folgenden Formulierungen in einer Stellenanzeige verstößt gegen das Allgemeine Gleichbehandlungsgesetz (AGG)?",
           ["Sie passen in unser junges dynamisches Team, wenn Sie jünger als 30 Jahre sind.", "Sie verfügen über hervorragende Kenntnisse in Webprogrammierung.", "Sie sind mobil und bereit, auch mehrtägige Geschäftsreisen zu unternehmen.", "Sie sind an flexible Arbeitszeiten gewöhnt und können gelegentlich abends länger arbeiten.", "Sie beherrschen die englische Sprache verhandlungssicher in Wort und Schrift."],
           "Ziffer 2. Benachteiligung wegen des Alters."),
    ]
}
